      "domanda": "Cinque uffici (Delta, Beta, Gamma, Alfa, Epsilon) trasmettono il proprio rendiconto al Rettore in cinque giorni consecutivi da lunedì a venerdì (uno al giorno). Sappiamo che: Delta trasmette prima di Beta; Gamma trasmette il lunedì; Alfa trasmette subito dopo Beta; Epsilon trasmette il venerdì. Quale ufficio trasmette il mercoledì?",
